
USE [master]
GO

CREATE DATABASE [WebDav]
GO

USE [WebDav]
GO

SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE TABLE [dbo].[Item](
     [ItemId] [uniqueidentifier] NOT NULL
    ,[ItemType] [int] NOT NULL
    ,[ParentItemId] [uniqueidentifier] NOT NULL
    ,[Name] [nvarchar](255) NOT NULL
    ,[Created] [datetime] NOT NULL
    ,[Modified] [datetime] NOT NULL
    ,[ContentType] [nvarchar](255) NULL
    ,[Content] varbinary(max) NULL
    ,[SerialNumber] [int] NULL
        ,[TotalContentLength] bigint NOT NULL
    ,[LastChunkSaved] [datetime] NULL
            CONSTRAINT [PK_Item] PRIMARY KEY CLUSTERED([ItemId] ASC)
)
GO

CREATE UNIQUE NONCLUSTERED INDEX [IX_Item] ON [dbo].[Item] 
(
    [ParentItemId] ASC,
    [Name] ASC
)
GO

CREATE TABLE [dbo].[Property](
    [PropertyId] [uniqueidentifier] NOT NULL DEFAULT NEWID(),
    [ItemId] [uniqueidentifier] NOT NULL,
    [Name] [nvarchar](255) NOT NULL,
    [Namespace] [nvarchar](100) NOT NULL,
    [PropVal] [nvarchar](255) NOT NULL,
    CONSTRAINT [PK_Property] PRIMARY KEY CLUSTERED ([PropertyId] ASC)
)
GO

CREATE UNIQUE NONCLUSTERED INDEX [IX_Property] ON [dbo].[Property]
(
    [Name] ASC,
    [Namespace] ASC,
    [ItemId] ASC
)
GO

CREATE TABLE [dbo].[Lock](
    [Token] [nvarchar](36) NOT NULL,
    [ItemId] [uniqueidentifier] NOT NULL,
    [Shared] [bit] NOT NULL,
    [Deep] [bit] NOT NULL,
    [Expires] [datetime] NOT NULL,
    [Owner] [nvarchar](255) NULL,
    CONSTRAINT [PK_Lock] PRIMARY KEY CLUSTERED ([Token] ASC)
)
GO


